'use client'
import React, { useEffect, useRef, useState } from 'react'
import gsap from 'gsap'
import WantedStarsHUD from './WantedStarsHUD'

interface CityRevealProps {
    onComplete: () => void
}

export default function CityReveal({ onComplete }: CityRevealProps) {
    const imgRef = useRef<HTMLImageElement | null>(null)
    const [time, setTime] = useState<string>('')

    useEffect(() => {
        const updateTime = () => {
            const now = new Date()
            const d = now
                .toLocaleDateString('en-US', {
                    weekday: 'short',
                    year: 'numeric',
                    month: 'short',
                    day: '2-digit',
                })
                .toUpperCase()
            const t = now.toLocaleTimeString('en-US', {
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
                hour12: false,
            })
            setTime(`${d}  ${t}`)
        }
        updateTime()
        const interval = setInterval(updateTime, 1000)

        // Cinematic Camera Drift & Reveal
        if (imgRef.current) {
            gsap.fromTo(
                imgRef.current,
                { opacity: 0, scale: 1.12, x: 10, y: 5 },
                {
                    opacity: 1,
                    scale: 1.0,
                    x: -10,
                    y: -5,
                    duration: 4.2,
                    ease: 'sine.out',
                }
            )
        }

        const timer = setTimeout(onComplete, 3800)

        return () => {
            clearTimeout(timer)
            clearInterval(interval)
            if (imgRef.current) gsap.killTweensOf(imgRef.current)
        }
    }, [onComplete])

    return (
        <div
            style={{
                position: 'fixed',
                inset: 0,
                background: '#000',
                overflow: 'hidden',
                zIndex: 100,
            }}
        >
            <img
                ref={imgRef}
                src="/images/intro_city.jpg"
                alt="Los Santos Skyline"
                style={{
                    position: 'absolute',
                    inset: '-5%',
                    width: '110%',
                    height: '110%',
                    objectFit: 'cover',
                    opacity: 0,
                    filter: 'contrast(1.15) brightness(0.9)',
                }}
            />
            <div className="heavy-vignette" />
            <div className="noise-overlay" />
            <div className="crt-scanlines" />

            {/* Top Bar with Location & Wanted Stars HUD */}
            <div
                style={{
                    position: 'absolute',
                    top: 36,
                    left: 44,
                    right: 44,
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'flex-start',
                    zIndex: 120,
                }}
            >
                <div
                    className="hud-jitter city-reveal-hud"
                    style={{
                        display: 'flex',
                        flexDirection: 'column',
                        gap: '4px',
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        textTransform: 'uppercase',
                        textShadow: '0 2px 8px rgba(0,0,0,0.9)',
                    }}
                >
                    <div style={{ fontSize: '1.1rem', letterSpacing: '0.22em', color: '#ffffff', fontWeight: 'bold' }}>
                        LOS SANTOS // SAN ANDREAS
                    </div>
                    <div style={{ fontSize: '0.85rem', letterSpacing: '0.18em', color: 'rgba(255,255,255,0.7)' }}>
                        {time} • 78°F CLEAR
                    </div>
                </div>

                <WantedStarsHUD count={5} size={20} />
            </div>
        </div>
    )
}
